/* eslint-disable @stencil-community/required-jsdoc */
import { Component, ComponentInterface, Element, Host, Prop, State, h } from '@stencil/core';
import { DatePickerViewMode } from '../../types';
import type { Dayjs } from 'dayjs';
import { getViewModeConfig } from '../../view-modes';
import { DateGridSharedContract } from './types';
import { computed } from '@src/shared/perf/cache';
import { addPeriodToDate } from '../../utils';
import { ViewModeConfig } from '../../view-modes/utils';

const prefix = 'date-grid';

@Component({
  tag: 'ks-date-time-picker-date-grid',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerDateGrid implements DateGridSharedContract, ComponentInterface {
  @Element() el!: HTMLKsDateTimePickerDateGridElement;

  @Prop() viewMode!: DatePickerViewMode;
  @Prop() viewDate!: Dayjs;
  @Prop() availableViewModes!: DatePickerViewMode[];

  /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
  @Prop() isRange = false;
  @Prop() value!: [Dayjs | null, Dayjs | null];
  @Prop() now!: Dayjs;
  @Prop() disabledDate!: (
    date: Dayjs,
    info: { type: 'date' | 'preset'; from?: Dayjs; to?: Dayjs; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  @Prop() disabled!: [boolean, boolean];
  @Prop() presetPreviewDate!: [Dayjs | null, Dayjs | null] | null;

  @Prop() displayMode!: 'single' | 'dual';
  @Prop() selectionPhase!: 'start' | 'end' | 'idle';
  @Prop() handleValueChange!: (value: [Dayjs | null, Dayjs | null]) => void;
  @Prop() handleViewChange!: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;
  @Prop() handleHoverPartChange!: (hoverPart: 'start' | 'end' | null) => void;

  @State() private hoverValue: Dayjs | null = null;

  private get viewModeConfig() {
    return getViewModeConfig(this.viewMode);
  }

  private getInlineEndDateGridViewDate = computed((viewDate: Dayjs, viewModeConfig: ViewModeConfig) =>
    addPeriodToDate(viewDate, 1, viewModeConfig.period),
  );

  private handleHoverValueChange = (value: Dayjs | null, hoverPart: 'start' | 'end' | null) => {
    this.hoverValue = value;
    this.handleHoverPartChange(hoverPart);
  };

  render() {
    const dateGridHeaderProps = {
      class: `${prefix}__header`,
      viewMode: this.viewMode,
      availableViewModes: this.availableViewModes,
      handleViewChange: this.handleViewChange,
    };

    const dateGridBodyProps = {
      class: `${prefix}__body`,
      now: this.now,
      value: this.value,
      viewMode: this.viewMode,
      availableViewModes: this.availableViewModes,
      selectionPhase: this.selectionPhase,
      isRange: this.isRange,
      hoverValue: this.hoverValue,
      disabled: this.disabled,
      disabledDate: this.disabledDate,
      presetPreviewDate: this.presetPreviewDate,
      handleValueChange: this.handleValueChange,
      handleViewChange: this.handleViewChange,
      handleHoverValueChange: this.handleHoverValueChange,
    };

    return (
      <Host>
        <div class={prefix}>
          <div>
            <ks-date-time-picker-date-grid-header
              layoutMode={this.displayMode === 'dual' ? 'inline-start' : 'standalone'}
              viewDate={this.viewDate}
              {...dateGridHeaderProps}
            />
            <ks-date-time-picker-date-grid-body viewDate={this.viewDate} {...dateGridBodyProps} />
          </div>

          {this.displayMode === 'dual' && (
            <div class={`${prefix}__inline-end`}>
              <ks-date-time-picker-date-grid-header
                layoutMode="inline-end"
                viewDate={this.getInlineEndDateGridViewDate(this.viewDate, this.viewModeConfig)}
                {...dateGridHeaderProps}
              />
              <ks-date-time-picker-date-grid-body
                viewDate={this.getInlineEndDateGridViewDate(this.viewDate, this.viewModeConfig)}
                {...dateGridBodyProps}
              />
            </div>
          )}
        </div>
      </Host>
    );
  }
}
